const assert = require('node:assert');
const { greet } = require('./greet');

test('greet returns formatted greeting for a name', () => {
  const result = greet('Alice');
  assert.strictEqual(typeof result, 'string');
  assert.ok(result.includes('Alice'));
});

test('greet handles empty string gracefully', () => {
  const result = greet('');
  assert.strictEqual(typeof result, 'string');
  assert.ok(result.length > 0);
});

test('greet handles null gracefully', () => {
  const result = greet(null);
  assert.strictEqual(typeof result, 'string');
  assert.ok(result.length > 0);
});

test('greet handles undefined gracefully', () => {
  const result = greet(undefined);
  assert.strictEqual(typeof result, 'string');
  assert.ok(result.length > 0);
});

test('greet handles various valid names', () => {
  assert.ok(greet('Bob').includes('Bob'));
  assert.ok(greet('Charlie').includes('Charlie'));
  assert.ok(greet('Dr. Smith').includes('Dr. Smith'));
});

function greet(name) {
  if (!name || name.trim() === '') {
    return 'Welcome, friend!';
  }
  return `Welcome, ${name}!`;
}

module.exports = { greet };

